import boto3
from datetime import datetime

def compare_metric_series(payload, config=None):
    config = config or {}
    cloudwatch_client = boto3.client(
        'cloudwatch',
        region_name=os.getenv('AWS_REGION', 'us-east-1')
    )

    start_time = payload['start_time']
    end_time = payload['end_time']
    namespace = payload['namespace']
    metric_name = payload['metric_name']
    stat = payload['stat']
    period = payload['period']
    dimensions1 = payload['dimensions_filter1']
    dimensions2 = payload['dimensions_filter2']

    response = cloudwatch_client.get_metric_data(
        MetricDataQueries=[
            {
                'Id': 'metric_series_1',
                'MetricStat': {
                    'Metric': {
                        'Namespace': namespace,
                        'MetricName': metric_name,
                        'Dimensions': dimensions1
                    },
                    'Period': period,
                    'Stat': stat,
                },
                'ReturnData': True,
            },
            {
                'Id': 'metric_series_2',
                'MetricStat': {
                    'Metric': {
                        'Namespace': namespace,
                        'MetricName': metric_name,
                        'Dimensions': dimensions2
                    },
                    'Period': period,
                    'Stat': stat,
                },
                'ReturnData': True,
            },
        ],
        StartTime=start_time,
        EndTime=end_time,
        ScanBy='TimestampAscending'
    )

    result = {
        "metric_series_1": {
            "timestamps": [],
            "values": []
        },
        "metric_series_2": {
            "timestamps": [],
            "values": []
        }
    }

    for metric_data_result in response.get('MetricDataResults', []):
        if metric_data_result['Id'] == 'metric_series_1':
            result['metric_series_1']['timestamps'] = [t.isoformat() for t in metric_data_result.get('Timestamps', [])]
            result['metric_series_1']['values'] = metric_data_result.get('Values', [])
        elif metric_data_result['Id'] == 'metric_series_2':
            result['metric_series_2']['timestamps'] = [t.isoformat() for t in metric_data_result.get('Timestamps', [])]
            result['metric_series_2']['values'] = metric_data_result.get('Values', [])
